function spring(c,x,X,y,colour=C.mint){const pts=[[x,y],[x+9,y]];for(let k=0;k<24;k++)pts.push([x+12+(X-x-24)*(k+.5)/24,y+(k%2?10:-10)]);pts.push([X-9,y],[X,y]);path(c,pts,colour,2.5)}
