function signedGraph(c,fn,extent,scale,colour=C.mint,x=88,y=316,w=520,h=70){line(c,x,y,x+w,y,C.line,1);const pts=[];for(let k=0;k<=200;k++)pts.push([x+k*w/200,y-fn(extent*k/200)/scale*h]);path(c,pts,colour,2.5)}

M.parallax=p=>({error:p.height*Math.tan(p.angle*Math.PI/180),reading:p.truePosition+p.height*Math.tan(p.angle*Math.PI/180)});
