M.throw=(p,t=0)=>{let T=(p.speed+Math.sqrt(p.speed**2+2*g*p.height))/g,q=Math.min(mod(t,T+1),T);return{T,time:q,y:Math.max(0,p.height+p.speed*q-.5*g*q*q),v:p.speed-g*q,H:p.height+p.speed**2/(2*g)}};
add({base:'kinematics',id:'vertical-throw',title:'Vertical throw and the turning point',description:'Throw a ball upward and follow height, velocity, and acceleration through its highest point.',formula:'v = u − gt; y = h₀ + ut − ½gt²',observe:'Velocity is zero only for an instant at the top. Acceleration is still downward there.',try:'Pause close to the turning point and switch on Show physics.',controls:[R('speed','Upward launch speed',5,25,1,15,'m/s'),R('height','Launch height',0,10,1,3,'m')],metrics:(p,t)=>{let z=M.throw(p,t);return[N('Height above ground',`${F(z.y)} m`),N('Signed velocity',`${F(z.v)} m/s`),N('Highest point',`${F(z.H)} m`)]},renderer(c,p,t){let z=M.throw(p,t),s=240/z.H,x=190,y=370-z.y*s;line(c,60,370,645,370,C.muted,3);line(c,x,115,x,370,C.line,1,[4,4]);dot(c,x,y,13,C.gold,true);if(z.time<z.T)arrow(c,x+30,y,x+30,y-clamp(z.v*3,-72,72),C.mint,3);arrow(c,x-30,y,x-30,y+47,C.blue,2);text(c,'g ↓',x-67,y+26,C.blue,14);text(c,z.time>=z.T?'LANDED':Math.abs(z.v)<1?'TURNING POINT':z.v>0?'RISING':'FALLING',65,99,C.mint,17);signedGraph(c,q=>p.speed-g*q,z.T,Math.max(p.speed,Math.abs(p.speed-g*z.T)),C.mint,340,244,260,88);text(c,'Velocity / m/s',340,128,C.mint,14);text(c,'0',325,244,C.muted,12);text(c,'Time →',523,365,C.muted,13);dot(c,340+260*z.time/z.T,244-z.v/Math.max(p.speed,Math.abs(p.speed-g*z.T))*88,5,C.gold);measure(c,90,370,90,370-z.H*s,'',C.gold);text(c,`Maximum: ${F(z.H,1)} m`,350,398,C.gold,14)},worked:(p,t)=>{let z=M.throw(p,t);return`At t = ${F(z.time)} s: v = ${p.speed} − 9.8t = ${F(z.v)} m/s; a = −9.8 m/s² during flight.`},assumption:'Point particle, no air resistance, upward positive. A flight restarts after touching the ground; the velocity graph describes the flight up to impact.',presets:[['From ground',{height:0,speed:15}],['From a rooftop',{height:10,speed:15}]]});
M.vectors=p=>({x:p.a+p.b*Math.cos(p.angle*Math.PI/180),y:p.b*Math.sin(p.angle*Math.PI/180),r:Math.sqrt(Math.max(0,p.a**2+p.b**2+2*p.a*p.b*Math.cos(p.angle*Math.PI/180)))});
add({base:'projectile',id:'vector-addition',title:'Vector addition: the parallelogram',description:'Resolve two vectors into components and build their resultant, head to tail.',formula:'R² = A² + B² + 2AB cos θ',observe:'The resultant is the diagonal from the common tail. Opposite equal vectors cancel.',try:'Make the vectors equal and set the angle to 180°.',controls:[R('a','Vector A magnitude',1,8,.5,5,'units',1),R('b','Vector B magnitude',1,8,.5,4,'units',1),R('angle','Angle between vectors',0,180,5,60,'°')],metrics:p=>{let z=M.vectors(p);return[N('Resultant magnitude',`${F(z.r)} units`),N('Components (Rx, Ry)',`(${F(z.x)}, ${F(z.y)})`),N('Direction from A',z.r<1e-8?'Undefined: zero vector':`${F(Math.atan2(z.y,z.x)*180/Math.PI,1)}°`)]},renderer(c,p,t){let z=M.vectors(p),s=24,O=[250,345],A=[O[0]+p.a*s,O[1]],B=[O[0]+p.b*Math.cos(p.angle*Math.PI/180)*s,O[1]-z.y*s],E=[O[0]+z.x*s,O[1]-z.y*s];line(c,...A,...E,C.gold,1.5,[5,5]);line(c,...B,...E,C.blue,1.5,[5,5]);arrow(c,...O,...A,C.blue,3);arrow(c,...O,...B,C.gold,3);if(z.r>1e-8)arrow(c,...O,...E,C.mint,4);dot(c,...O,4,C.white);let q=mod(t,3)/3;dot(c,O[0]+(E[0]-O[0])*q,O[1]+(E[1]-O[1])*q,4,C.mint);text(c,'A',A[0],A[1]+26,C.blue,18,'center');text(c,'B',B[0]-15,B[1]-17,C.gold,18);text(c,z.r<1e-8?'A + B = 0':'R = A + B',75,106,C.mint,19);text(c,'Dashed edges complete the parallelogram',75,401,C.muted,14)},worked:p=>{let z=M.vectors(p);return`Rx = ${p.a} + ${p.b}cos ${p.angle}° = ${F(z.x)}; Ry = ${p.b}sin ${p.angle}° = ${F(z.y)}; |R| = ${F(z.r)}`},assumption:'Two coplanar vectors with arbitrary common units. Vector A points along +x; all arrows use the same length scale.',presets:[['Perpendicular',{a:3,b:4,angle:90}],['Complete cancellation',{a:5,b:5,angle:180}]]});
M.elevator=p=>({N:p.mass*(g+p.acceleration),weight:p.mass*g,apparent:p.mass*(1+p.acceleration/g)});
add({base:'forces',id:'elevator-weight',title:'Apparent weight in an elevator',description:'Accelerate an elevator and see how the floor’s normal reaction changes a weighing-scale reading.',formula:'N − mg = ma',observe:'A scale measures the normal force. During ideal free fall it reads zero even though gravity still acts.',try:'Try the free-fall preset, then reveal the free-body diagram.',controls:[R('mass','Passenger mass',40,100,5,60,'kg'),R('acceleration','Elevator acceleration (up +)',-9.8,9.8,.1,2,'m/s²',1)],metrics:p=>{let z=M.elevator(p);return[N('Scale force N',`${F(z.N,1)} N`),N('Scale reading (kg)',`${F(z.apparent,1)} kg`),N('True weight mg',`${F(z.weight,1)} N`)]},renderer(c,p,t){let q=mod(t,3)/3,dy=-p.acceleration*5*q*q,y=170+dy;for(let X of [154,526])line(c,X,89,X,403,C.line,3);rr(c,175,y,330,205,'#132a3b',C.muted,7);rr(c,285,y+157,110,25,'#1c5960',C.mint,4);let z=M.elevator(p);dot(c,340,y+57,19,C.gold);line(c,340,y+76,340,y+119,C.gold,7);line(c,340,y+119,315,y+153,C.gold,5);line(c,340,y+119,365,y+153,C.gold,5);line(c,312,y+94,368,y+94,C.gold,4);text(c,`${F(z.apparent,1)} kg`,340,y+170,C.white,15,'center');if(p.acceleration)arrow(c,563,y+100,563,y+100-Math.sign(p.acceleration)*57,C.blue,3);text(c,z.N<.01?'FREE FALL • N = 0':p.acceleration>0?'ACCELERATING UP':p.acceleration<0?'ACCELERATING DOWN':'ZERO ACCELERATION',74,101,C.mint,17);text(c,'Elevator position resets between demonstrations',78,409,C.muted,13)},worked:p=>`N = m(g+a) = ${p.mass}(9.8 + ${p.acceleration}) = ${F(M.elevator(p).N,1)} N`,assumption:'Passenger stays in contact with the floor for a ≥ −g. The scale is calibrated in kg using g = 9.8 m/s². Elevator motion is enlarged and restarts.',presets:[['Heavier reading',{acceleration:3}],['Free fall',{acceleration:-9.8}]]});
M.launch=(p,t=0)=>{let w=Math.sqrt(p.k/p.mass),release=Math.PI/(2*w),time=mod(t,release+1.5),a=p.compression/100,x=time<release?-a*Math.cos(w*time):a*w*(time-release),v=time<release?a*w*Math.sin(w*time):a*w,E=.5*p.k*a*a;return{w,release,time,x,v,E,U:time<release?.5*p.k*a*a*Math.cos(w*time)**2:0}};
add({base:'energy',id:'spring-launcher',title:'Spring launcher and energy transfer',description:'Release a compressed spring and watch elastic potential energy turn into the cart’s kinetic energy.',formula:'½kx₀² = ½mv²',observe:'The cart loses contact at the spring’s natural length and then travels at constant speed.',try:'Double compression and compare launch speed with stored energy.',controls:[R('k','Spring stiffness',20,100,10,50,'N/m'),R('mass','Cart mass',.5,3,.5,1,'kg',1),R('compression','Initial compression',5,30,1,15,'cm')],metrics:(p,t)=>{let z=M.launch(p,t);return[N('Launch speed',`${F(p.compression/100*Math.sqrt(p.k/p.mass))} m/s`),N('Spring energy',`${F(z.U,3)} J`),N('Kinetic energy',`${F(z.E-z.U,3)} J`)]},renderer(c,p,t){let z=M.launch(p,t),scale=Math.min(110,270/(p.compression/100*Math.sqrt(p.k/p.mass)*1.5)),x=320+z.x*scale;line(c,66,288,650,288,C.muted,3);rr(c,79,207,20,80,'#42576a',C.muted,2);spring(c,99,Math.min(x-30,290),257);cart(c,Math.min(x,610),274,'CART',C.gold);line(c,320,169,320,296,C.blue,1,[4,4]);text(c,'Natural length',260,137,C.blue,14);for(let [y,v,col,l] of [[340,z.U,C.gold,'SPRING'],[387,z.E-z.U,C.mint,'KINETIC']]){rr(c,180,y-12,430,23,'#102638',C.line,3);rr(c,180,y-12,430*v/z.E,23,col,null,3);text(c,l,72,y,C.muted,13)}text(c,z.time<z.release?'SPRING PUSHES THE CART':'FREE MOTION AFTER RELEASE',72,98,C.mint,16)},worked:p=>`vlaunch = x₀√(k/m) = ${p.compression/100}√(${p.k}/${p.mass}) = ${F(p.compression/100*Math.sqrt(p.k/p.mass))} m/s`,assumption:'Massless spring and a frictionless horizontal surface. The cart is not attached to the spring. Geometry is scaled; the animation restarts after release.',presets:[['15 cm compression',{compression:15}],['30 cm compression',{compression:30}]]});
M.rod=(p,t=0)=>{let I=p.mass*p.length**2/3,w=Math.sqrt(3*g/(2*p.length)),theta=p.angle*Math.PI/180*Math.cos(w*t);return{I,w,theta,period:TAU/w,torque:-p.mass*g*p.length/2*Math.sin(theta)}};
add({base:'rotation',id:'rod-pendulum',title:'A rod as a physical pendulum',description:'Swing a uniform rod about one end and connect rotational inertia with its oscillation period.',formula:'T ≈ 2π√(I / mgd)',observe:'Gravity acts at the centre of mass. The period is independent of mass for the same rod length.',try:'Double the rod’s mass, then double its length. Compare the changes.',controls:[R('length','Rod length',.5,2,.1,1.2,'m',1),R('mass','Rod mass',1,5,.5,2,'kg',1),R('angle','Release angle',5,20,1,12,'°')],metrics:(p,t)=>{let z=M.rod(p,t);return[N('Moment of inertia',`${F(z.I)} kg·m²`),N('Small-angle period',`${F(z.period)} s`),N('Gravity torque',`${F(z.torque)} N·m`)]},renderer(c,p,t){let z=M.rod(p,t),L=130+p.length*55,cx=344,cy=135,X=cx+L*Math.sin(z.theta),Y=cy+L*Math.cos(z.theta),mx=(cx+X)/2,my=(cy+Y)/2;line(c,228,125,455,125,C.muted,5);line(c,cx,cy,cx,cy+L,C.line,1,[4,4]);line(c,cx,cy,X,Y,C.blue,13);dot(c,cx,cy,8,C.white);dot(c,mx,my,6,C.gold);arrow(c,mx,my,mx,my+55,C.gold,3);text(c,'mg',mx+13,my+42,C.gold,16);text(c,'Pivot',cx+21,cy,C.white,14);text(c,'Centre of mass at L/2',74,99,C.gold,16);text(c,`θ = ${F(z.theta*180/Math.PI,1)}°`,490,253,C.mint,18);text(c,'Restoring torque acts about the pivot',79,401,C.muted,14)},worked:p=>`I = mL²/3 = ${F(M.rod(p).I)} kg·m²; T = 2π√(2L/3g) = ${F(M.rod(p).period)} s`,assumption:'Uniform rigid rod, frictionless pivot, small-angle motion. Displayed gravitational torque uses sin θ; the animated period uses the small-angle approximation.',presets:[['Light rod',{mass:1}],['Heavy rod',{mass:5}]]});
M.depth=p=>{let r=6371+p.altitude;return{r,field:p.altitude<0?g*r/6371:g*(6371/r)**2}};
add({base:'gravity',id:'gravity-depth',title:'Gravity above and below Earth',description:'Move a probe from inside Earth into space and compare the two different gravity laws.',formula:'Inside: g ∝ r; outside: g ∝ 1/r²',observe:'In a uniform-density Earth, gravity rises linearly from zero at the centre to its surface value.',try:'Compare equal distances above the surface and below it.',controls:[R('altitude','Height above surface (depth −)',-6000,4000,250,0,'km')],metrics:p=>[N('Distance from centre',`${M.depth(p).r} km`),N('Gravitational field',`${F(M.depth(p).field)} m/s²`),N('Location',p.altitude<0?'Inside Earth':p.altitude>0?'Above Earth':'At the surface')],renderer(c,p,t){let z=M.depth(p),cx=200,cy=260,R=91,x=cx+z.r/6371*R;dot(c,cx,cy,R,C.blue);arc(c,cx,cy,R*.55,0,TAU,'#e9f6ff44',1);line(c,cx,cy,350,cy,C.muted,1,[4,4]);dot(c,x,cy,7,C.gold,true);arrow(c,x,cy,x-z.field*5,cy,C.mint,3);text(c,'Toward the centre',78,399,C.mint,14);chart(c,{fn:r=>r<6371?g*r/6371:g*(6371/r)**2,xmax:11000,ymax:10,xlabel:'Radius / km',ylabel:'g / m/s²',marker:z.r,x:380,y:353,w:242,h:205});text(c,'Uniform-density Earth',73,102,C.blue,16)},worked:p=>p.altitude<0?`g(r) = 9.8×${M.depth(p).r}/6371 = ${F(M.depth(p).field)} m/s²`:`g(r) = 9.8×(6371/${M.depth(p).r})² = ${F(M.depth(p).field)} m/s²`,assumption:'Earth is spherical with uniform density. Real Earth has a varying density profile, so its interior gravity does not follow this simple straight line.',presets:[['1,000 km below',{altitude:-1000}],['1,000 km above',{altitude:1000}]]});
