add({base:'hooke',id:'spring-network',title:'Springs in series and parallel',description:'Join two springs and compare how much the same load stretches the combination.',formula:'Series: 1/k = 1/k₁ + 1/k₂',observe:'A series pair is softer than either spring. A parallel pair is stiffer than either spring.',try:'Use equal springs and switch between the two connections.',controls:[R('k1','Spring stiffness k₁',50,250,25,100,'N/m'),R('k2','Spring stiffness k₂',50,250,25,150,'N/m'),R('force','Applied force',5,20,1,10,'N'),S('mode','Connection','series',[['series','Series'],['parallel','Parallel']])],metrics:p=>[N('Equivalent stiffness',`${F(M.springs(p).k,1)} N/m`),N('Total extension',`${F(M.springs(p).x*100,1)} cm`),N('Elastic energy',`${F(.5*p.force*M.springs(p).x,3)} J`)],renderer(c,p,t){let z=M.springs(p),end=485+z.x*110;rr(c,80,150,22,215,'#42576a',C.muted,2);if(p.mode==='series'){spring(c,103,290,250,C.blue);spring(c,290,end,250,C.gold);text(c,'k₁',190,205,C.blue,17);text(c,'k₂',385,205,C.gold,17)}else{spring(c,103,end,195,C.blue);spring(c,103,end,303,C.gold);line(c,end,180,end,320,C.white,4);text(c,'k₁',285,154,C.blue,17);text(c,'k₂',285,352,C.gold,17)}arrow(c,end,250,Math.min(645,end+65),250,C.mint,3);text(c,`${p.force} N`,end+3,222,C.mint,16);measure(c,485,374,end,374,'',C.mint);text(c,'Extension magnified; springs obey Hooke’s law',70,404,C.muted,14);text(c,p.mode.toUpperCase()+' CONNECTION',72,101,C.white,17)},worked:p=>`keq = ${F(M.springs(p).k,1)} N/m; x = F/keq = ${F(M.springs(p).x*100,1)} cm`,assumption:'Massless ideal springs, static loading within the elastic range. The drawing magnifies extensions; a parallel pair has common end plates.',presets:[['Equal in series',{k1:100,k2:100,mode:'series'}],['Equal in parallel',{k1:100,k2:100,mode:'parallel'}]]});
