M.resonance=p=>{let w=TAU*p.frequency,k=TAU**2,A=p.force/Math.hypot(k-w*w,p.damping*w),phase=Math.atan2(p.damping*w,k-w*w);return{A,phase,w}};
add({base:'pendulum',id:'driven-resonance',title:'Driven oscillations and resonance',description:'Drive a damped oscillator near its natural frequency and watch its steady-state response build in amplitude.',formula:'A = F₀/√[(k−mω²)²+(bω)²]',observe:'The response peaks near the natural frequency. Damping limits the peak and changes the phase lag.',try:'Compare driving at 0.5 Hz and close to the 1.0 Hz natural frequency.',controls:[R('frequency','Driving frequency',.25,1.75,.05,1,'Hz',2),R('damping','Damping coefficient',.5,3.5,.25,1.5,'kg/s',2),R('force','Driving force amplitude',.5,3,.5,1,'N',1)],metrics:p=>{let z=M.resonance(p);return[N('Response amplitude',`${F(z.A*100,2)} cm`),N('Displacement phase lag',`${F(z.phase*180/Math.PI,1)}°`),N('Natural frequency','1.00 Hz') ]},renderer(c,p,t){let z=M.resonance(p),x=350+z.A*135*Math.cos(z.w*t-z.phase);rr(c,74,121,21,90,'#42576a',C.muted,2);spring(c,95,x-30,165);cart(c,x,181,'m = 1 kg',C.gold);line(c,60,202,642,202,C.muted,3);arrow(c,x,147,x+Math.cos(z.w*t)*p.force*25,147,C.blue,3);let fmax=Math.sqrt(Math.max(0,1-p.damping*p.damping/(2*TAU**2))),peak=M.resonance({...p,frequency:Math.max(.25,fmax)}).A;chart(c,{fn:f=>M.resonance({...p,frequency:f}).A*100,xmax:2,ymax:peak*110,xlabel:'Driving frequency / Hz',ylabel:'Amplitude / cm',marker:p.frequency,x:95,y:358,w:510,h:108});text(c,'Blue arrow: periodic driving force',77,98,C.blue,14)},worked:p=>`A = ${F(M.resonance(p).A*100,2)} cm; phase lag = ${F(M.resonance(p).phase*180/Math.PI,1)}°. Here m = 1 kg and k = 4π² N/m.`,assumption:'Linear forced oscillator in steady state; transients are omitted. Natural frequency is 1 Hz. The displacement is proportional to the calculated response.',presets:[['Off resonance',{frequency:.5}],['Near resonance',{frequency:1}]]});
add({base:'wave',id:'beats',title:'Beats: two notes, one pulsing sound',description:'Superpose two nearby frequencies and see the amplitude rise and fall in beats.',formula:'fbeat = |f₁ − f₂|',observe:'The rapid oscillations sit inside a slowly changing envelope. Each loudness maximum is one beat.',try:'Turn on Sound, then bring the frequencies closer together.',controls:[R('f1','Frequency f₁',2,6,.1,4,'Hz',1),R('f2','Frequency f₂',2,6,.1,4.5,'Hz',1),R('amplitude','Each wave amplitude',.5,1.5,.1,1,'units',1)],metrics:p=>[N('Beat frequency',`${F(Math.abs(p.f1-p.f2),1)} Hz`),N('Beat period',p.f1===p.f2?'No beats':`${F(1/Math.abs(p.f1-p.f2),2)} s`),N('Maximum amplitude',`${F(2*p.amplitude,1)} units`)],renderer(c,p,t){let pts=[],up=[],down=[];for(let k=0;k<=600;k++){let q=t+k/600*4,Y=p.amplitude*(Math.sin(TAU*p.f1*q)+Math.sin(TAU*p.f2*q)),env=2*p.amplitude*Math.abs(Math.cos(Math.PI*(p.f1-p.f2)*q)),x=65+k*580/600;pts.push([x,262-Y*40]);up.push([x,262-env*40]);down.push([x,262+env*40])}line(c,65,262,645,262,C.line,1);path(c,up,C.gold,1.5);path(c,down,C.gold,1.5);path(c,pts,C.mint,2);text(c,'Gold envelope • green resultant',76,105,C.gold,16);text(c,'4-second moving window',76,403,C.muted,14);text(c,'Sound uses a higher carrier; beat rate stays the same',75,377,C.muted,13)},worked:p=>`fbeat = |${p.f1.toFixed(1)} − ${p.f2.toFixed(1)}| = ${F(Math.abs(p.f1-p.f2),1)} Hz`,assumption:'Two equal-amplitude sinusoidal waves at one point. Audio shifts both frequencies upward by 216 Hz so they are audible, preserving their difference and beat rate.',presets:[['Slow beats',{f1:4,f2:4.2}],['Faster beats',{f1:4,f2:5}]]});
