add({base:'capacitor',id:'equipotential-map',title:'Equipotentials around a point charge',description:'Move a probe around a charge and connect electric potential with field direction.',formula:'V = kQ/r; E = k|Q|/r²',observe:'Moving around one circular equipotential costs no electrostatic work. Moving radially changes potential.',try:'Keep radius fixed and change the probe angle through a complete circle.',controls:[R('charge','Source charge',-5,5,1,3,'nC'),R('radius','Probe radius',.3,2,.1,1,'m',1),R('angle','Probe angle',0,360,5,35,'°')],metrics:p=>[N('Potential at probe',`${F(8.988*p.charge/p.radius)} V`),N('Field magnitude',`${F(8.988*Math.abs(p.charge)/p.radius**2)} N/C`),N('Energy of +1 nC probe',`${F(8.988*p.charge/p.radius)} nJ`)],renderer(c,p,t){let cx=345,cy=252,a=p.angle*Math.PI/180,R=p.radius*71,x=cx+R*Math.cos(a),y=cy-R*Math.sin(a);for(let r of [.5,1,1.5,2]){arc(c,cx,cy,r*71,0,TAU,p.charge<0?C.blue:C.gold,1);text(c,`${r.toFixed(1)} m: ${F(8.988*p.charge/r,1)} V`,63,155+r*75,C.muted,13)}dot(c,cx,cy,17,p.charge<0?C.blue:C.gold,true);text(c,p.charge>0?'+':p.charge<0?'−':'0',cx,cy,'#112230',23,'center');dot(c,x,y,7,C.mint,true);line(c,cx,cy,x,y,C.muted,1,[4,4]);if(p.charge)arrow(c,x,y,x+Math.sign(p.charge)*43*Math.cos(a),y-Math.sign(p.charge)*43*Math.sin(a),C.mint,3);text(c,'Probe: potential and field at the same point',76,104,C.mint,15);text(c,'Equipotentials are perpendicular to E',91,403,C.muted,15)},worked:p=>`V = 8.988×${p.charge}/${p.radius} = ${F(8.988*p.charge/p.radius)} V; U = qprobeV for qprobe = +1 nC.`,assumption:'Point charge in vacuum; zero potential at infinity. Circles are cross-sections of spherical equipotentials. A test charge does not disturb the field.',presets:[['Positive source',{charge:3}],['Negative source',{charge:-3}]]});
