M.selector=p=>{let B=p.field/1000,E=p.electric,v=p.speed*1e5,w=9.5788e7*B,ve=E/B;return{B,E,v,w,ve,Fe:1.602e-19*E,Fb:1.602e-19*v*B,point:t=>[ve*t+(v-ve)*Math.sin(w*t)/w,(v-ve)*(Math.cos(w*t)-1)/w]}};
